CREATE TABLE IF NOT EXISTS bookmark (
  id                   TEXT PRIMARY KEY,
  url                  TEXT NOT NULL,
  url_key              TEXT NOT NULL UNIQUE,
  title_captured       TEXT,
  title_user           TEXT,
  description_captured TEXT,
  description_user     TEXT,
