        <button onClick={() => p.onSetUnread(false)}>Mark read</button>
        {p.scope === 'archived' ? (
          <button onClick={() => p.onArchive(false)}>Restore</button>
        ) : (
          <button onClick={() => p.onArchive(true)}>Archive</button>
        )}
