  onTagClick: (tag: string) => void;
}

/** One bookmark row: title, description, tags, favicon (FR-028). Activating the
 *  title opens the original link in a new tab (FR-029); the checkbox is a
 *  separate multi-select control for bulk actions. */
export function BookmarkRow({ b, selected, onToggleSelect, onEdit, onTagClick }: Props) {
  const meta = b.captureStatus.metadata;
  return (
    <div className="bookmark">
      <input
        className="check"
        type="checkbox"
        checked={selected}
        onChange={() => onToggleSelect(b.id)}
        aria-label="Select bookmark"
      />
      {b.favicon ? (
        <img className="fav" src={b.favicon} alt="" onError={(e) => (e.currentTarget.style.visibility = 'hidden')} />
      ) : (
        <span className="fav" />
      )}
      <div className="body">
        <div className="row-flex wrap">
          <span className="title">
            <a href={b.url} target="_blank" rel="noopener noreferrer">
              {b.title}
            </a>
          </span>
          {b.unread && <span className="badge unread">unread</span>}
          {meta === 'pending' && <span className="badge">capturing…</span>}
          {meta === 'failed' && <span className="badge">metadata unavailable</span>}
        </div>
        <div className="url">{b.url}</div>
        {b.description && <div className="desc">{b.description}</div>}
        {b.tags.length > 0 && (
          <div className="tags">
            {b.tags.map((t) => (
              <span key={t} className="tag" onClick={() => onTagClick(t)}>
                #{t}
              </span>
            ))}
          </div>
        )}
      </div>
      <div className="row-flex" style={{ flexDirection: 'column', gap: 6 }}>
        <button onClick={() => onEdit(b)}>Edit</button>
      </div>
    </div>
  );
}
import { useState } from 'react';

interface Props {
  selectedCount: number;
  totalMatching: number;
  selectAllMatching: boolean;
  onSelectAllMatching: (on: boolean) => void;
  onClear: () => void;
  onAddTags: (tags: string[]) => void;
  onRemoveTags: (tags: string[]) => void;
  onSetUnread: (unread: boolean) => void;
  onArchive: (archived: boolean) => void;
  onDelete: () => void;
  scope: string;
}

/** Bulk action bar. "Select all matching" targets the complete current view
 *  server-side (FR-019), not just the visible page. */
export function BulkBar(p: Props) {
  const [tagText, setTagText] = useState('');
  if (p.selectedCount === 0 && !p.selectAllMatching) return null;
  const effective = p.selectAllMatching ? p.totalMatching : p.selectedCount;
  const tags = () =>
    tagText
      .split(',')
      .map((t) => t.trim())
      .filter(Boolean);

  return (
    <div className="bulk-bar">
      <div className="row-flex wrap">
        <strong>{effective} selected</strong>
        {!p.selectAllMatching && p.totalMatching > p.selectedCount && (
          <button onClick={() => p.onSelectAllMatching(true)}>
            Select all {p.totalMatching} matching this view
          </button>
        )}
        {p.selectAllMatching && <span className="muted">(all matching the current view)</span>}
        <button onClick={p.onClear}>Clear</button>
      </div>
      <div className="row-flex wrap" style={{ marginTop: 8 }}>
        <input
          type="text"
          style={{ maxWidth: 220 }}
          placeholder="tag1, tag2"
          value={tagText}
          onChange={(e) => setTagText(e.target.value)}
        />
        <button onClick={() => tags().length && p.onAddTags(tags())}>Add tags</button>
        <button onClick={() => tags().length && p.onRemoveTags(tags())}>Remove tags</button>
        <button onClick={() => p.onSetUnread(true)}>Mark unread</button>
        <button onClick={() => p.onSetUnread(false)}>Mark read</button>
        {p.scope === 'archived' ? (
          <button onClick={() => p.onArchive(false)}>Restore</button>
        ) : (
          <button onClick={() => p.onArchive(true)}>Archive</button>
        )}
        <button className="danger" onClick={p.onDelete}>
          Delete
        </button>
      </div>
    </div>
  );
}
